      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class DynamicResolutionManager : MonoBehaviour
{
    [Header("Configurações de Resolução")]
    [Range(0.5f, 1.0f)] public float minRenderScale = 0.65f;
    [Range(0.5f, 1.0f)] public float maxRenderScale = 1.0f;
    public float targetFrameTimeMs = 16.0f;
    public float adjustmentSpeed = 0.05f;
    public float checkInterval = 0.25f;

    private float _timeSinceLastCheck;
    private float _currentRenderScale = 1.0f;
    private FrameTiming[] _frameTimings = new FrameTiming[1];

    private void Start()
    {
        _currentRenderScale = maxRenderScale;
        ScalableBufferManager.ResizeBuffers(_currentRenderScale, _currentRenderScale);
    }

    private void Update()
    {
        _timeSinceLastCheck += Time.unscaledDeltaTime;
        if (_timeSinceLastCheck < checkInterval)
            return;

        _timeSinceLastCheck = 0f;
        FrameTimingManager.CaptureFrameTimings();
        uint captured = FrameTimingManager.GetLatestTimings(1, _frameTimings);

        float currentGpuMs = captured > 0 ? (float)_frameTimings[0].gpuFrameTime : Time.unscaledDeltaTime * 1000f;

        if (currentGpuMs > targetFrameTimeMs && _currentRenderScale > minRenderScale)
        {
            _currentRenderScale = Mathf.Max(minRenderScale, _currentRenderScale - adjustmentSpeed);
            ScalableBufferManager.ResizeBuffers(_currentRenderScale, _currentRenderScale);
        }
        else if (currentGpuMs < (targetFrameTimeMs - 2.0f) && _currentRenderScale < maxRenderScale)
        {
            _currentRenderScale = Mathf.Min(maxRenderScale, _currentRenderScale + adjustmentSpeed);
            ScalableBufferManager.ResizeBuffers(_currentRenderScale, _currentRenderScale);
        }
    }
}",
      "explicacao_didatica": "A placa de vídeo (GPU) está demorando quase o dobro do tempo permitido (28.27 ms em vez de 16.67 ms) para desenhar os pixels de cada quadro na tela. O script implementado usa a tecnologia de Resolução Dinâmica nativa da Unity: quando a GPU começa a sofrer para manter os 60 FPS, a resolução interna da imagem é reduzida de forma suave e automática, diminuindo o número de pixels calculados e aliviando imediatamente a placa de vídeo."
    },
    {
      "tipo": "GC",
      "causa_raiz": "Pico de Garbage Collection de 5.60 ms causado por alocação transitória de memória de aproximadamente 96 KB no frame 3081, ultrapassando a margem de tempo de CPU sem travamentos.",
      "codigo_refatorado": "using System.Collections.Generic;
using UnityEngine;

public class NonAllocCollisionObserver : MonoBehaviour
{
    [SerializeField] private float detectionRadius = 10f;
    [SerializeField] private LayerMask targetLayer;

    // Array reutilizado para evitar alocação de memória no Garbage Collector
    private readonly Collider[] _hitBuffer = new Collider[32];
    private readonly List<Collider> _validTargets = new List<Collider>(32);

    private void Update()
    {
        ScanTargetsNoAlloc();
    }

    private void ScanTargetsNoAlloc()
    {
        _validTargets.Clear();
        int hitCount = Physics.OverlapSphereNonAlloc(transform.position, detectionRadius, _hitBuffer, targetLayer);

        for (int i = 0; i < hitCount; i++)
        {
            Collider hit = _hitBuffer[i];
            if (hit != null)
            {
                _validTargets.Add(hit);
            }
        }
    }
}",
      "explicacao_didatica": "Em jogos, criar e descartar variáveis temporárias a cada frame gera 'lixo' de memória. Quando a lixeira enche, a Unity precisa parar o jogo por 5.6 milissegundos para limpá-la, provocando pequenas travadas (stuttering). O código acima reutiliza sempre a mesma lista e o mesmo array pré-alocados em memória, eliminando a criação de lixo e mantendo a taxa de quadros fluida."
    }
  ],
  "dicas_level_design": null
}

